import { POLICY, nearest, decide, metrics } from './decision.mjs';

const $ = (s, root=document) => root.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
 shield:'M12 3 20 6v6c0 5-8 9-8 9s-8-4-8-9V6z M8.5 12l2.5 2.5 4.5-5',
 building:'M3 21V7h10v14 M13 11h8v10 M6 10h1m3 0h0M6 14h1m3 0h0M6 18h1m3 0h0M16 14h2m-2 4h2M1 21h22',
 scan:'M8 3H4a1 1 0 0 0-1 1v4m13-5h4a1 1 0 0 1 1 1v4M3 16v4a1 1 0 0 0 1 1h4m8 0h4a1 1 0 0 0 1-1v-4M8 10v1m8-1v1m-7 5q3 3 6 0M12 9v4h1',
 users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M17 4a4 4 0 0 1 0 7m2 4a4 4 0 0 1 3 4v2',
 flask:'M9 3h6M10 3v6l-6 10a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3L14 9V3M8 15h8',
 layers:'m12 3 10 5-10 5L2 8zm-10 9 10 5 10-5m-20 5 10 5 10-5',
 lock:'M6 10h12a1 1 0 0 1 1 1v9a1 1 0 0 1-1 1H6a1 1 0 0 1-1-1v-9a1 1 0 0 1 1-1m2 0V7a4 4 0 0 1 8 0v3m-4 4v3',
 help:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5m0 3h.01',
 camera:'M8 5 6 8H3v12h18V8h-3l-2-3z M12 10a4 4 0 1 0 0 8 4 4 0 0 0 0-8',
 clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 4v5l3 2',
 check:'m5 12 4 4L19 6', close:'m6 6 12 12M6 18 18 6',
 info:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20m0 8v7m0-10h.01',
 download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',
 upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5',
 plus:'M12 5v14M5 12h14', search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14m5 12 6 6',
 face:'M12 2c-6 0-9 4-9 10s4 10 9 10 9-4 9-10-3-10-9-10M7 9h1m8 0h1m-5 1v4h2m-6 3q4 3 8 0',
 photo:'M3 3h18v18H3z M3 16l6-6 6 6 3-3 3 3M16 7h.01',
 screen:'M3 3h18v14H3zm9 14v4m-4 0h8',
 video:'M4 3h16v18H4zm6 5 6 4-6 4z',
 mask:'M3 4q9 4 18 0v8c0 5-9 10-9 10S3 17 3 12zm4 6 3 1m4 0 3-1m-8 7q3-3 6 0',
 arrow:'M5 12h14m-5-5 5 5-5 5',
 refresh:'M20 10a8 8 0 0 0-14-5L3 8m0-5v5h5m-4 6a8 8 0 0 0 14 5l3-3m0 5v-5h-5',
 activity:'M2 12h5l3-9 4 18 3-9h5', trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',
 play:'m8 4 12 8-12 8z'
};
const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.shield}"/></svg>`;
function hydrate(root=document){root.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));}
let users=[], events=[], storageOK=true;
try { users=JSON.parse(localStorage.getItem('aegis.users.v1')||'[]'); events=JSON.parse(localStorage.getItem('aegis.events.v1')||'[]'); if(!Array.isArray(users)||!Array.isArray(events))throw Error(); } catch {users=[];events=[];storageOK=false;}
let route='', stream=null, modelsReady=false, modelPromise=null, busy=false, lastResult=null, selectedScenario='genuine', enrollStream=null, enrollment=null, toastTimer, enrollmentEpoch=0;
const labels={allow:'Allow',deny:'Deny',review:'Request verification'};
const scenarios={genuine:{name:'Genuine',icon:'face',description:'A live, enrolled person. Follow the on-screen prompt. Use a known enrolled identity so non-allow results count as false rejections.'},print:{name:'Printed photo',icon:'photo',description:'Present a printed portrait of an enrolled person. Keep it in the frame during the randomized prompt.'},screen:{name:'Screen photo',icon:'screen',description:'Show an enrolled portrait on a phone or monitor. Test several brightness levels and viewing angles.'},video:{name:'Video replay',icon:'video',description:'Replay a video of an enrolled person. A replay containing the requested action may defeat this prototype. Record the observed outcome.'},mask:{name:'3D / print mask',icon:'mask',description:'Present a mask under controlled conditions. RGB active prompts do not reliably reject realistic 3D masks. A production PAD model and depth/IR hardware need separate evaluation.'}};
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{toast('Browser storage is unavailable or full. No data was saved.');return false;}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function percent(n){return n==null?'—':`${(n*100).toFixed(1)}%`;}
function ms(n){return n==null?'—':`${(n/1000).toFixed(2)} s`;}
function pill(e){return `<span class="pill ${e.outcome}">${icon(e.outcome==='allow'?'check':e.outcome==='deny'?'close':'info')}${labels[e.outcome]}</span>`;}
function date(t){return new Date(t).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'});}
function header(kicker,title,subtitle,action=''){return `<div class="page-heading"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${action}</div>`;}
function stats(){const m=metrics(events);return `<div class="stats"><div class="stat"><div class="stat-head">Verifications ${icon('scan')}</div><div class="stat-value">${m.count}<small>sessions</small></div><div class="stat-note"><span class="dot"></span>Measured camera checks</div></div><div class="stat"><div class="stat-head">Average decision ${icon('clock')}</div><div class="stat-value">${m.mean==null?'—':(m.mean/1000).toFixed(2)}<small>seconds</small></div><div class="stat-note">${m.p95==null?'Awaiting your first check':`P95 · ${ms(m.p95)}`}</div></div><div class="stat"><div class="stat-head">Enrolled identities ${icon('users')}</div><div class="stat-value">${users.filter(u=>u.active).length}<small>active people</small></div><div class="stat-note">${users.length?'Ready for identity matching':'Add your first person to begin'}</div></div><div class="stat"><div class="stat-head">Decision budget ${icon('shield')}</div><div class="stat-value">2.00<small>seconds</small></div><div class="stat-note"><span class="dot"></span>Timeout → request verification</div></div></div>`;}
const faceIllustration=`<div class="face-visual"><i class="corner tl"></i><i class="corner tr"></i><i class="corner bl"></i><i class="corner br"></i><svg viewBox="0 0 180 230" aria-hidden="true"><defs><pattern id="face-dots" width="9" height="9" patternUnits="userSpaceOnUse"><circle cx="4" cy="4" r=".7" fill="#b2d58d"/></pattern><clipPath id="face-clip"><path d="M90 20C42 20 27 51 29 94l9 63c7 25 37 48 52 48s45-23 52-48l9-63C153 51 138 20 90 20Z"/></clipPath></defs><path d="M90 20C42 20 27 51 29 94l9 63c7 25 37 48 52 48s45-23 52-48l9-63C153 51 138 20 90 20Z" stroke-width=".5" stroke-dasharray="2 4" fill="url(#face-dots)"/><g clip-path="url(#face-clip)" stroke-width=".4" opacity=".45"><path d="m25 78 130 70M25 148 155 78M25 120h130M90 20v185M30 90l60-40 60 40M35 160l55-50 55 50M45 170l45 23 45-23M28 95l62 98 62-98M40 55l50 138 50-138"/></g><g stroke-width="1"><path d="M48 95q12-8 24 0m36 0q12-8 24 0M86 104l-7 29 11 5 11-5-7-29M67 157q23 13 46 0m-39 1q16-5 32 0"/></g><circle cx="60" cy="95" r="2" fill="#b9df8a"/><circle cx="120" cy="95" r="2" fill="#b9df8a"/><circle cx="90" cy="135" r="2" fill="#b9df8a"/></svg><div class="scan-line"></div></div>`;
function resultHTML(){const r=lastResult;return `<div class="card-head"><h3>${icon('shield')}Verification result</h3><span class="tag">${r?'COMPLETED':'STANDBY'}</span></div><div class="result-body"><div class="result-symbol">${icon(r?(r.outcome==='allow'?'check':r.outcome==='deny'?'close':'info'):'scan')}</div><div class="result-kicker">${r?(r.demo?'ILLUSTRATIVE DEMO':'CAMERA CHECK'):'READY WHEN YOU ARE'}</div><div class="result-title">${r?labels[r.outcome]:'Let’s meet the real you.'}</div><p class="result-description">${r?esc(r.reason):'Start a live check to verify a person’s presence and match their identity.'}</p>${r?`<div class="result-person">${esc(r.name || 'Identity not confirmed')}</div>`:''}<div class="check-list"><div class="check-row"><span>${r?.liveness?'✓':'01'}</span>Active liveness<em>${r?(r.liveness?'Prompt passed':'Not confirmed'):'Awaiting check'}</em></div><div class="check-row"><span>${r?.distance!=null?'✓':'02'}</span>Identity match<em>${r?(r.distance!=null?`Distance ${r.distance.toFixed(3)}`:'No match'):'Awaiting check'}</em></div><div class="check-row"><span>${r?'✓':'03'}</span>Access decision<em class="result-timing">${r?`${ms(r.elapsed)}${r.demo?' · simulated':''}`:'≤ 2 s target'}</em></div></div><div class="progress-track" id="scan-progress" hidden><div class="progress-fill"></div></div></div><div class="result-bottom"><span>${icon('lock')} ${r?.demo?'Excluded from all performance metrics':'Active checks · prototype policy'}</span><a href="#architecture">How it works ↗</a></div>`;}
function eventTable(list,all=false){return `<div class="table-scroll"><table><thead><tr><th>IDENTITY</th><th>TIME</th><th>RESULT</th><th>DECISION TIME</th><th>${all?'TEST LABEL':'SOURCE'}</th></tr></thead><tbody>${list.length?list.map(e=>`<tr><td><strong>${esc(e.name||'Unconfirmed identity')}</strong>${e.demo?'<span class="badge-sample">DEMO</span>':''}</td><td>${date(e.timestamp)}</td><td>${pill(e)}</td><td>${ms(e.elapsed)}${e.elapsed>2000?' · over budget':''}</td><td>${e.demo?'Simulated scenario':esc(scenarios[e.groundTruth]?.name || 'Live camera')}</td></tr>`).join(''):`<tr><td colspan="5" class="empty-table">${icon('activity')}No verifications yet. Your first check will appear here.</td></tr>`}</tbody></table></div>`;}
function verifyPage(){return `${header('IDENTITY, WITH CERTAINTY','See the person. Stop the spoof.','A live face. A known identity. One confident decision.',`<button class="btn secondary" id="demo-button">${icon('play')}Try guided demo</button>`)}${stats()}<div class="verification-grid"><section class="card"><div class="card-head"><h3>${icon('camera')}Live capture</h3><span class="tag" id="camera-status"><i></i>Camera offline</span></div><div class="camera" id="camera-stage"><video id="verify-video" autoplay playsinline muted hidden></video><div class="camera-top"><span class="camera-label"><i></i> AEGIS VISION</span><span class="camera-chip">LOCAL · RGB CAMERA</span></div>${faceIllustration}<div class="camera-bottom"><strong id="camera-prompt">Your presence is the proof.</strong><p id="camera-hint">Enable your camera to begin a secure session.</p></div></div><div class="camera-actionbar"><span class="camera-footnote">${icon('lock')}Frames never leave your device</span><div class="camera-controls"><button class="btn secondary" id="stop-camera" hidden aria-label="Stop camera">${icon('close')}</button><button class="btn lime" id="start-camera">${icon('camera')}Enable camera</button></div></div></section><section class="card result-card ${lastResult?.outcome||''}" id="result-card" aria-live="polite">${resultHTML()}</section></div><section class="card"><div class="card-head recent-head"><h3>Recent verifications <span class="pill neutral">${events.length}</span></h3><button class="text-btn" id="export">Export log ${icon('download')}</button></div>${eventTable(events.slice(0,5))}</section><p class="bottom-note">${icon('info')}Prototype: randomized active prompts help test static-photo attacks. Replay and 3D-mask resistance are unvalidated. No production gate should rely on these results.</p>`;}
function peopleRows(list){return list.length?list.map(u=>`<tr><td><div class="person-cell"><img src="${u.photo}" alt=""><div><strong>${esc(u.name)}</strong><small>${esc(u.reference||u.id.slice(0,8))}</small></div></div></td><td>${esc(u.team||'General')}</td><td><span class="pill ${u.active?'allow':'neutral'}">${u.active?'Active':'Suspended'}</span></td><td>${new Date(u.created).toLocaleDateString()}</td><td><div class="row-actions"><button class="text-btn" data-toggle="${u.id}">${u.active?'Suspend':'Activate'}</button><button class="text-btn danger" data-delete="${u.id}" aria-label="Delete ${esc(u.name)}">${icon('trash')}</button></div></td></tr>`).join(''):`<tr><td colspan="5" class="empty-table">No people match your search.</td></tr>`;}
function peoplePage(){return `${header('ADMINISTRATION','Good access starts with good enrollment.','Create and manage the identities your kiosk recognizes.',`<button class="btn primary" id="add-person">${icon('plus')}Enroll person</button>`)}<div class="revoke-notice">Local administrator workspace · Anyone with access to this browser can manage identities. Use only for supervised prototype testing.</div><div class="toolbar"><label class="searchbox">${icon('search')}<input id="people-search" type="search" placeholder="Search name, team or reference ID" aria-label="Search enrolled people"></label><span class="subtitle">${users.length} identities · ${users.filter(u=>u.active).length} active</span></div><section class="card">${users.length?`<div class="table-scroll"><table><thead><tr><th>PERSON</th><th>TEAM</th><th>STATUS</th><th>ENROLLED</th><th>ACTIONS</th></tr></thead><tbody id="people-rows">${peopleRows(users)}</tbody></table></div>`:`<div class="empty-people"><span>${icon('users')}</span><h2>Put a name to a face.</h2><p>Enroll your first person to make live identity matching possible.</p><button class="btn primary" id="enroll-empty">${icon('plus')}Enroll your first person</button></div>`}</section><p class="bottom-note">${icon('lock')}Names, reference photos and face descriptors are saved in this browser. Deleting a person also removes their named session history.</p>`;}
function labPage(){const m=metrics(events);return `${header('MEASURE. CHALLENGE. IMPROVE.','Put the proof to the test.','Run controlled attempts, label the evidence, and measure what happens.',`<button class="btn secondary" id="export">${icon('download')}Export test results</button>`)}<div class="lab-layout"><section class="card lab-panel"><span class="eyebrow">CONTROLLED CAMERA TEST</span><h2>What’s in front of the camera?</h2><p class="section-intro" style="margin-top:10px">Choose the known test condition before a real camera attempt. Labels are supplied by you, not inferred by the model.</p><div class="scenario-grid">${Object.entries(scenarios).map(([key,s])=>`<button class="scenario ${selectedScenario===key?'selected':''}" data-scenario="${key}" aria-pressed="${selectedScenario===key}">${icon(s.icon)}${s.name}</button>`).join('')}</div><div class="lab-detail"><strong>${scenarios[selectedScenario].name} test</strong>${scenarios[selectedScenario].description}</div><button class="btn primary" id="run-lab">${icon('camera')}Run labeled camera check ${icon('arrow')}</button></section><section class="card lab-side"><span class="eyebrow">REAL SESSIONS ONLY</span><h2>Evidence, not assumptions.</h2><div class="metric-line"><span>Attack acceptance rate <small>(APCER*)</small></span><b>${percent(m.apcer)}</b></div><div class="metric-line"><span>Genuine non-allow rate <small>(FRR*)</small></span><b>${percent(m.frr)}</b></div><div class="metric-line"><span>Checks within 2 seconds</span><b>${percent(m.within)}</b></div><div class="metric-line"><span>Request verification rate</span><b>${percent(m.review)}</b></div><p class="fine-print">${m.attacks} labeled attacks · ${m.genuine} labeled genuine attempts.<br>*Operational prototype metrics. Genuine non-allow includes review. A review is not a confirmed spoof detection. These are not certified PAD error rates.</p></section></div><section class="card"><div class="card-head"><h3>Test history</h3><span class="tag">${events.filter(e=>e.groundTruth&&!e.demo).length} labeled sessions</span></div>${eventTable(events.filter(e=>e.groundTruth&&!e.demo),true)}</section><p class="bottom-note">${icon('info')}Collect genuine and spoof attempts under varied light, distance, devices and subjects. No accuracy claim is shown until actual trials exist.</p><section class="card" style="margin-top:22px;padding:22px"><h3>Explore the decision states</h3><p class="section-intro" style="margin:9px 0 15px">Clearly labeled simulations for presenting the interface. These do not test spoof detection and never enter measured statistics.</p><div class="inline-actions"><button class="btn secondary" data-demo="allow">${icon('check')}Allow</button><button class="btn secondary" data-demo="review">${icon('info')}Request verification</button><button class="btn secondary" data-demo="deny">${icon('close')}Deny</button></div></section>`;}
function architecturePage(){return `${header('INSPIRED BY DIGIYATRA','Trust is a sequence, not a face match.','A layered approach to presence, identity and access.')}<div class="architecture-hero"><span class="eyebrow" style="color:#c7dc9f">THE IDEA BEHIND AEGIS</span><h2>Verify the identity.<br>Then verify who’s actually here.</h2><p>DigiYatra’s public architecture links a verified reference identity to a live facial capture and an access decision. Aegis adapts that separation for a supervised hackathon prototype. It is independent of DigiYatra and does not reproduce its proprietary anti-spoofing engine.</p></div><div class="flow"><div class="flow-step"><span class="step-number">01 / ENROLL</span><h3>A trusted starting point</h3><p>An admin checks identity, records consent, and captures a face reference. A 128-value descriptor is stored locally with the person’s name.</p></div><div class="flow-step"><span class="step-number">02 / CAPTURE</span><h3>Quality before certainty</h3><p>The camera checks for one face, adequate lighting and usable size. Poor quality routes to additional verification.</p></div><div class="flow-step"><span class="step-number">03 / CHALLENGE</span><h3>A fresh action, each time</h3><p>A randomly selected blink or head turn is measured from successive landmarks. Face descriptors must stay consistent across samples.</p></div><div class="flow-step"><span class="step-number">04 / DECIDE</span><h3>Three clear outcomes</h3><p>Allow a strong match plus completed prompt; deny a clear mismatch or suspended identity; request verification for uncertainty or timeout.</p></div></div><div class="architecture-columns"><section class="card prose-card"><h2>What the public sources say</h2><p>The Ministry’s policy describes a liveness-enabled selfie matched to an e-KYC reference, with a credential stored in a smartphone wallet. AWS describes credential sharing with the departure airport and live-to-reference face matching. These are architectural principles, not a published anti-spoofing model.</p><p style="margin-top:13px">AAI’s procurement requirements specify passive liveness and fake detection without head or facial movements. Aegis uses active prompts instead. The challenge sheet’s two-second target is a separate requirement; it is not a DigiYatra performance guarantee.</p><div class="sources"><strong>Primary sources</strong><a target="_blank" rel="noopener" href="https://civilaviation.gov.in/sites/default/files/2023-07/Digi%20Yatra%20Policy%20%28DIGI%20YATRA%29.pdf">Ministry of Civil Aviation · DigiYatra policy ↗</a><a target="_blank" rel="noopener" href="https://aws.amazon.com/solutions/case-studies/digi-yatra-foundation/">AWS · DigiYatra Foundation case study ↗</a><a target="_blank" rel="noopener" href="https://www.aai.aero/sites/default/files/basic_page_files/Request%20for%20Budgetary%20Offer_DigiYatra_ATD.pdf">Airports Authority of India · FRT requirements, §6.7 ↗</a></div></section><section class="card prose-card"><h2>Where the prototype ends</h2><ul><li>Face recognition uses face-api.js. Liveness is an uncalibrated landmark heuristic, not a trained passive PAD model.</li><li>Static portraits should fail a blink prompt, but replay videos, masks and camera injection can pass active checks. These attacks need independent testing.</li><li>The two-second clock starts after camera and model initialization. Actual wall-clock decision time is recorded, including overruns. Late results cannot allow access.</li><li>Templates and photos are not encrypted in browser storage. There is no server-side admin authentication or trusted access controller.</li><li>For deployment: add authenticated admins, protected templates, a server-validated fresh session, evaluated passive PAD, and depth/IR where required.</li></ul><div class="note"><span>${icon('shield')}</span><p>No AWS services or external biometric APIs are connected. The challenge’s AWS sandbox would require its own backend integration and credentials.</p></div></section></div><section class="card prose-card" style="margin-top:20px"><h2>Your device, your controls.</h2><p>Face video is processed on this device. Only enrolled reference thumbnails, face descriptors, names and session results are retained in this browser. They persist until deleted or browser data is cleared. The app does not upload biometric data to a server.</p><div style="margin-top:17px" class="inline-actions"><button id="export" class="btn secondary">${icon('download')}Export session log</button><button id="clear-data" class="btn secondary danger">${icon('trash')}Erase all local data</button></div><p class="fine-print">Erasing data removes all local identities, reference portraits, descriptors and session records. This cannot be undone.</p></section>`;}
let pendingGroundTruth=null;
function render(){if(busy){toast('Finish the active check before navigating.');return;}const next=location.hash.slice(1)||'verify';route=['verify','people','lab','architecture'].includes(next)?next:'verify';stopStream();$('#breadcrumb').textContent={verify:'Live verification',people:'People & enrollment',lab:'Test lab',architecture:'How it works'}[route];document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===route);if(a.dataset.nav===route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#nav-count').textContent=users.length;$('#main').innerHTML=`<div class="screen-enter">${{verify:verifyPage,people:peoplePage,lab:labPage,architecture:architecturePage}[route]()}</div>`;hydrate();bind();if(!storageOK)toast('Saved data could not be read. Avoid enrollment until browser storage is available.');}
function bind(){ $('#start-camera')?.addEventListener('click',()=>stream?runScan():startCamera());$('#stop-camera')?.addEventListener('click',stopCameraUI);$('#demo-button')?.addEventListener('click',()=>runDemo('allow'));$('#add-person')?.addEventListener('click',openEnrollment);$('#enroll-empty')?.addEventListener('click',openEnrollment);$('#export')?.addEventListener('click',exportCSV);$('#people-search')?.addEventListener('input',e=>{const rows=$('#people-rows');if(rows)rows.innerHTML=peopleRows(users.filter(u=>`${u.name} ${u.team} ${u.reference}`.toLowerCase().includes(e.target.value.toLowerCase())));bindPeople();});bindPeople();document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>{selectedScenario=b.dataset.scenario;render();});document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>runDemo(b.dataset.demo));$('#run-lab')?.addEventListener('click',()=>{pendingGroundTruth=selectedScenario;location.hash='verify';toast(`Labeled test: ${scenarios[selectedScenario].name}. Enable the camera, then start the check.`);});$('#clear-data')?.addEventListener('click',()=>{if(!confirm('Erase every local identity, reference photo and session record? This cannot be undone.'))return;users=[];events=[];lastResult=null;localStorage.removeItem('aegis.users.v1');localStorage.removeItem('aegis.events.v1');render();toast('All local biometric data and logs erased.');});}
function bindPeople(){document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{const updated=users.map(u=>u.id===b.dataset.toggle?{...u,active:!u.active}:u);if(persist('aegis.users.v1',updated)){users=updated;render();toast('Identity access updated.');}});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{const u=users.find(u=>u.id===b.dataset.delete);if(!confirm(`Delete ${u.name}'s reference, face templates and named session history?`))return;const updated=users.filter(x=>x.id!==u.id),history=events.filter(e=>e.userId!==u.id);if(persist('aegis.users.v1',updated)){users=updated;if(persist('aegis.events.v1',history))events=history;lastResult=null;render();toast('Identity and named history deleted.');}});}
async function loadModels(){if(modelsReady)return;if(modelPromise)return modelPromise;modelPromise=(async()=>{if(!globalThis.faceapi)throw Error('Recognition library could not load. Reload this page.');await Promise.resolve(faceapi.tf.setBackend('webgl')).catch(()=>faceapi.tf.setBackend('cpu'));await Promise.all([faceapi.nets.tinyFaceDetector.loadFromUri('./models'),faceapi.nets.faceLandmark68TinyNet.loadFromUri('./models'),faceapi.nets.faceRecognitionNet.loadFromUri('./models')]);const blank=document.createElement('canvas');blank.width=320;blank.height=240;await faceapi.detectAllFaces(blank,new faceapi.TinyFaceDetectorOptions({inputSize:320}));await faceapi.nets.faceLandmark68TinyNet.detectLandmarks(blank);await faceapi.nets.faceRecognitionNet.computeFaceDescriptor(blank);modelsReady=true;})();try{await modelPromise;}catch(e){modelPromise=null;throw e;}}
function cameraError(e){return e.name==='NotAllowedError'?'Camera permission was denied. Allow camera access in your browser, then retry.':e.name==='NotFoundError'?'No camera found. Connect a webcam and retry.':e.name==='NotReadableError'?'Camera is in use by another application. Close it and retry.':e.message||'Camera unavailable. Use HTTPS or localhost and retry.';}
async function getCamera(){if(!navigator.mediaDevices?.getUserMedia)throw Error('Camera requires HTTPS or localhost in a supported browser.');return navigator.mediaDevices.getUserMedia({audio:false,video:{width:{ideal:640},height:{ideal:480},facingMode:'user'}});}
async function attachVideo(video,s){video.srcObject=s;await video.play();if(video.readyState<2)await new Promise((resolve,reject)=>{video.onloadeddata=resolve;setTimeout(()=>reject(Error('Camera did not provide frames.')),8000);});}
let cameraAttempt=0;
async function startCamera(){const button=$('#start-camera');if(!button)return;const attempt=++cameraAttempt;button.disabled=true;button.innerHTML=`${icon('refresh')}Preparing camera…`;$('#camera-hint').textContent='Loading local face models. This is outside the timed check.';let nextStream;try{await Promise.all([getCamera().then(s=>{nextStream=s;}),loadModels()]);if(attempt!==cameraAttempt||route!=='verify'){nextStream.getTracks().forEach(t=>t.stop());return;}stream=nextStream;await attachVideo($('#verify-video'),stream);$('#verify-video').hidden=false;$('.face-visual').style.opacity='.3';$('#camera-status').innerHTML='<i></i>Camera ready';$('#camera-prompt').textContent=pendingGroundTruth?`${scenarios[pendingGroundTruth].name} · labeled test`:'Face forward. Follow the prompt when it appears.';$('#camera-hint').textContent=users.length?'The next check has a two-second decision budget.':'Enroll a person in People & enrollment before verification.';$('#stop-camera').hidden=false;button.innerHTML=`${icon('scan')}Start verification`;button.disabled=!users.length;stream.getVideoTracks()[0].addEventListener('ended',()=>{if(!busy)stopCameraUI();});}catch(e){nextStream?.getTracks().forEach(t=>t.stop());if(attempt===cameraAttempt&&route==='verify'){toast(cameraError(e));$('#camera-hint').textContent=cameraError(e);button.disabled=false;button.innerHTML=`${icon('camera')}Retry camera`;}}}
function stopStream(){cameraAttempt++;if(stream){stream.getTracks().forEach(t=>t.stop());stream=null;}}
function stopCameraUI(){if(busy)return;stopStream();const v=$('#verify-video');if(v){v.srcObject=null;v.hidden=true;$('.face-visual').style.opacity='';$('#camera-status').innerHTML='<i></i>Camera offline';$('#camera-prompt').textContent='Your presence is the proof.';$('#camera-hint').textContent='Enable your camera to begin a secure session.';$('#start-camera').innerHTML=`${icon('camera')}Enable camera`;$('#start-camera').disabled=false;$('#stop-camera').hidden=true;}}
const pause = ms=>new Promise(r=>setTimeout(r,ms));
function makeFrame(video){const c=document.createElement('canvas');c.width=320;c.height=Math.round(320*video.videoHeight/video.videoWidth)||240;c.getContext('2d',{willReadFrequently:true}).drawImage(video,0,0,c.width,c.height);return c;}
function quality(frame,box){const f=box.width/frame.width;if(f<.2||f>.85||box.x<0||box.y<0)return false;const c=frame.getContext('2d',{willReadFrequently:true}),d=c.getImageData(Math.max(0,box.x),Math.max(0,box.y),Math.min(box.width,frame.width-box.x),Math.min(box.height,frame.height-box.y)).data;let sum=0,sq=0,n=0;for(let i=0;i<d.length;i+=32){const l=.2126*d[i]+.7152*d[i+1]+.0722*d[i+2];sum+=l;sq+=l*l;n++;}const mean=sum/n;return mean>42&&mean<226&&sq/n-mean*mean>130;}
function eyeRatio(p){const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);return (dist(p[1],p[5])+dist(p[2],p[4]))/(2*dist(p[0],p[3]));}
function landmarkSignals(l){const left=l.getLeftEye(),right=l.getRightEye(),center=a=>a.reduce((s,p)=>s+p.x,0)/a.length;const lx=center(left),rx=center(right);return{eye:(eyeRatio(left)+eyeRatio(right))/2,yaw:(l.getNose()[3].x-(lx+rx)/2)/Math.abs(rx-lx)};}
function updateResult(){const card=$('#result-card');if(card){card.className=`card result-card ${lastResult?.outcome||''}`;card.innerHTML=resultHTML();}}
async function runScan(){if(busy||!stream)return;if(!users.length){toast('Enroll a person first.');return;}busy=true;const video=$('#verify-video'),startButton=$('#start-camera');startButton.disabled=true;$('#stop-camera').disabled=true;const choices=['blink','left','right'],challenge=choices[crypto.getRandomValues(new Uint32Array(1))[0]%choices.length];const prompt={blink:'Blink once, then open your eyes.',left:'Turn your face to your left.',right:'Turn your face to your right.'}[challenge];$('#camera-prompt').innerHTML=`<span class="prompt">${prompt}</span>`;$('#camera-hint').textContent='Keep one face in frame · checking presence + identity';$('#camera-stage').classList.add('active-scan');const progress=$('#scan-progress');progress.hidden=false;const fill=$('.progress-fill',progress);let final=false, liveness=false, baseline=null, maxEye=0,closed=false, reopened=false, multiple=false,usable=0,faceFrames=0,ranked=[],identities=[],sampleDistances=[],inflight=false;const started=performance.now();
 const clock=setInterval(()=>{if(fill)fill.style.width=`${Math.min(100,(performance.now()-started)/20)}%`;},40);
 const finish=()=>{if(final)return;final=true;clearInterval(clock);clearTimeout(deadline);const elapsed=performance.now()-started;const evidence={elapsed,multiple,samples:usable,quality:usable>=2,consistent:identities.length>=2&&identities.every(i=>i===identities[0]),distance:sampleDistances.length?Math.max(...sampleDistances):null,margin:ranked.length>1?ranked[1].distance-ranked[0].distance:Infinity,active:ranked[0]?.user.active,liveness};const result=decide(evidence);const confident=ranked[0]&&evidence.distance<=POLICY.match&&evidence.margin>=POLICY.margin&&evidence.consistent;const user=confident?ranked[0].user:null;const e={id:crypto.randomUUID(),timestamp:Date.now(),...result,elapsed,name:user?.name||null,userId:user?.id||null,distance:evidence.distance,liveness,challenge,usableFrames:usable,groundTruth:pendingGroundTruth,demo:false};pendingGroundTruth=null;lastResult=e;const next=[e,...events].slice(0,500);if(persist('aegis.events.v1',next))events=next;updateResult();$('#camera-prompt').textContent=result.outcome==='allow'?`Welcome, ${user.name}.`:labels[result.outcome];$('#camera-hint').textContent=elapsed>2000?'Recorded over budget · access cannot be allowed.':result.reason;$('#camera-stage').classList.remove('active-scan');startButton.innerHTML=`${icon('refresh')}Check another person`;startButton.disabled=false;$('#stop-camera').disabled=false;busy=false;const t=$('.stats');if(t)t.outerHTML=stats();const recent=$('.recent-head')?.parentElement;if(recent){recent.innerHTML=`<div class="card-head recent-head"><h3>Recent verifications <span class="pill neutral">${events.length}</span></h3><button class="text-btn" id="export">Export log ${icon('download')}</button></div>${eventTable(events.slice(0,5))}`;$('#export').onclick=exportCSV;}if(location.hash.slice(1)&&location.hash.slice(1)!==route)render();};
 const deadline=setTimeout(finish,1990);
 try{while(!final){inflight=true;const frame=makeFrame(video);const found=await faceapi.detectAllFaces(frame,new faceapi.TinyFaceDetectorOptions({inputSize:320,scoreThreshold:.6})).withFaceLandmarks(true).withFaceDescriptors();inflight=false;if(final)break;if(performance.now()-started>POLICY.deadline){finish();break;}if(found.length>1){multiple=true;finish();break;}if(found.length===1){faceFrames++;const d=found[0];if(d.detection.score>.7&&quality(frame,d.detection.box)){usable++;const ranks=nearest(Array.from(d.descriptor),users);ranked=ranks;identities.push(ranks[0]?.user.id);sampleDistances.push(ranks[0]?.distance);const s=landmarkSignals(d.landmarks);if(baseline===null)baseline=s;maxEye=Math.max(maxEye,s.eye);if(challenge==='blink'){if(maxEye>.23&&s.eye<Math.min(.21,maxEye*.72))closed=true;if(closed&&s.eye>maxEye*.88)reopened=true;liveness=reopened;}else{const change=s.yaw-baseline.yaw;liveness ||= challenge==='left'?change>.15:change<-.15;}if(liveness&&usable>=2){finish();break;}}}await pause(20);}}catch(e){if(!final){toast(`Inference interrupted: ${e.message}`);finish();}}finally{inflight=false;}}
async function runDemo(outcome){if(busy)return;pendingGroundTruth=null;stopStream();if(route!=='verify'){location.hash='verify';await pause(80);}if(route!=='verify')render();busy=true;const b=$('#demo-button');b.disabled=true;const prompt=$('#camera-prompt');prompt.textContent='Guided demo · simulated check';$('#camera-hint').textContent='Illustration only. No camera data or real spoof test.';const p=$('#scan-progress');p.hidden=false;const f=$('.progress-fill',p);const start=performance.now();for(let i=0;i<=10;i++){if(f)f.style.width=`${i*10}%`;await pause(130);}lastResult={id:crypto.randomUUID(),timestamp:Date.now(),demo:true,outcome,name:outcome==='allow'?'Alex Morgan · sample identity':null,liveness:outcome==='allow',distance:outcome==='allow'?.32:null,elapsed:1500,reason:{allow:'Simulated identity match and completed prompt. No live camera check was performed.',review:'Simulated low-light capture. Ask the person to retry or use an attended identity check.',deny:'Simulated presentation attack. This example demonstrates the deny state, not measured detection.'}[outcome]};events=[lastResult,...events].slice(0,500);persist('aegis.events.v1',events);busy=false;render();toast('Demo complete. Simulated results are excluded from measured metrics.');}
function exportCSV(){if(!events.length){toast('No sessions to export yet.');return;}const columns=['id','timestamp','name','outcome','reason','elapsed','distance','liveness','challenge','usableFrames','groundTruth','demo'];const cell=v=>'"'+String(v??'').replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"';const csv='\ufeff'+columns.join(',')+'\r\n'+events.map(e=>columns.map(k=>cell(k==='timestamp'?new Date(e[k]).toISOString():e[k])).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`aegis-sessions-${new Date().toISOString().slice(0,10)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Session log exported. Demo rows are explicitly marked.');}
function setEnrollStatus(message,error=false){const el=$('#enroll-status');el.textContent=message;el.classList.toggle('error',error);}
function stopEnrollStream(){enrollStream?.getTracks().forEach(t=>t.stop());enrollStream=null;$('#enroll-video').srcObject=null;$('#capture').hidden=true;}
function openEnrollment(){enrollmentEpoch++;stopCameraUI();enrollment=null;$('#enroll-form').reset();setEnrollStatus('');$('#enroll-preview').hidden=true;$('#enroll-video').hidden=true;$('#enroll-placeholder').hidden=false;$('#save-person').disabled=false;$('#enroll-camera').disabled=false;$('#enroll-dialog').showModal();}
$('#enroll-camera').onclick=async()=>{const b=$('#enroll-camera');b.disabled=true;setEnrollStatus('Preparing local face models and camera…');try{stopEnrollStream();const s=await getCamera();if(!$('#enroll-dialog').open){s.getTracks().forEach(t=>t.stop());return;}enrollStream=s;$('#enroll-video').hidden=false;$('#enroll-preview').hidden=true;$('#enroll-placeholder').hidden=true;await Promise.all([attachVideo($('#enroll-video'),s),loadModels()]);if(!$('#enroll-dialog').open)return;$('#capture').hidden=false;setEnrollStatus('Look straight ahead in good lighting, then capture.');}catch(e){stopEnrollStream();setEnrollStatus(cameraError(e),true);}finally{b.disabled=false;}};
async function extractEnrollment(source){await loadModels();const input=source instanceof HTMLVideoElement?makeFrame(source):source;const found=await faceapi.detectAllFaces(input,new faceapi.TinyFaceDetectorOptions({inputSize:416,scoreThreshold:.7})).withFaceLandmarks(true).withFaceDescriptors();if(found.length!==1)throw Error(found.length?'More than one face found. Use a portrait of one person.':'No face found. Use a clear, front-facing portrait.');const d=found[0];if(d.detection.score<.8)throw Error('Face detection is uncertain. Improve lighting and use a clearer portrait.');const width=input.width||input.naturalWidth, height=input.height||input.naturalHeight;if(d.detection.box.width/width<.15)throw Error('Face is too small. Move closer or crop the portrait.');const descriptor=Array.from(d.descriptor);const dup=nearest(descriptor,users)[0];if(dup&&dup.distance<.45)throw Error(`This face is already enrolled as ${dup.user.name}. Manage that identity instead.`);const c=document.createElement('canvas');c.width=160;c.height=160;const box=d.detection.box;const side=Math.min(Math.max(box.width,box.height)*1.4,width,height);const x=Math.max(0,Math.min(width-side,box.x+box.width/2-side/2)),y=Math.max(0,Math.min(height-side,box.y+box.height/2-side/2));c.getContext('2d').drawImage(input,x,y,side,side,0,0,160,160);return{descriptor,photo:c.toDataURL('image/jpeg',.8)};}
$('#capture').onclick=async()=>{const epoch=++enrollmentEpoch;const b=$('#capture');b.disabled=true;$('#save-person').disabled=true;setEnrollStatus('Extracting face reference…');try{if(!enrollStream)throw Error('Enable the enrollment camera first.');const candidate=await extractEnrollment($('#enroll-video'));if(epoch!==enrollmentEpoch||!$('#enroll-dialog').open)return;enrollment=candidate;$('#enroll-preview').src=enrollment.photo;$('#enroll-preview').hidden=false;$('#enroll-video').hidden=true;stopEnrollStream();setEnrollStatus('Face reference captured. Add the name and consent to finish.');}catch(e){if(epoch===enrollmentEpoch)setEnrollStatus(e.message,true);}finally{b.disabled=false;if(epoch===enrollmentEpoch)$('#save-person').disabled=false;}};
$('#photo-upload').onchange=async e=>{const epoch=++enrollmentEpoch;const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024){setEnrollStatus('Use an image smaller than 10 MB.',true);return;}if(!['image/jpeg','image/png','image/webp'].includes(file.type)){setEnrollStatus('Use a JPEG, PNG or WebP portrait.',true);return;}stopEnrollStream();enrollment=null;$('#save-person').disabled=true;setEnrollStatus('Checking portrait and extracting a face template…');let url;try{url=URL.createObjectURL(file);const image=new Image();image.src=url;await image.decode();if(epoch!==enrollmentEpoch||!$('#enroll-dialog').open)return;$('#enroll-preview').src=url;$('#enroll-preview').hidden=false;$('#enroll-video').hidden=true;$('#enroll-placeholder').hidden=true;const c=document.createElement('canvas');const scale=Math.min(1,960/Math.max(image.naturalWidth,image.naturalHeight));c.width=Math.round(image.naturalWidth*scale);c.height=Math.round(image.naturalHeight*scale);c.getContext('2d').drawImage(image,0,0,c.width,c.height);const candidate=await extractEnrollment(c);if(epoch!==enrollmentEpoch||!$('#enroll-dialog').open)return;enrollment=candidate;$('#enroll-preview').src=enrollment.photo;$('#enroll-preview').hidden=false;$('#enroll-video').hidden=true;$('#enroll-placeholder').hidden=true;setEnrollStatus('Face reference ready. This photo is not a liveness check.');}catch(e){if(epoch===enrollmentEpoch)setEnrollStatus(e.message,true);}finally{if(url)URL.revokeObjectURL(url);if(epoch===enrollmentEpoch)$('#save-person').disabled=false;}};
$('#enroll-form').onsubmit=e=>{e.preventDefault();if(!enrollment){setEnrollStatus('Capture or upload a face reference first.',true);return;}const data=new FormData(e.target),name=data.get('name').trim(),reference=data.get('reference').trim();if(name.length<2){setEnrollStatus('Enter a name with at least two characters.',true);return;}if(reference&&users.some(u=>u.reference.toLowerCase()===reference.toLowerCase())){setEnrollStatus('That reference ID is already in use.',true);return;}const person={id:crypto.randomUUID(),name,team:data.get('team').trim(),reference,active:true,created:Date.now(),consent:true,descriptors:[enrollment.descriptor],photo:enrollment.photo};const next=[person,...users];if(persist('aegis.users.v1',next)){users=next;$('#enroll-dialog').close();render();toast(`${name} enrolled. Ready for live verification.`);}};
$('#close-enroll').onclick=()=>$('#enroll-dialog').close();$('#enroll-dialog').addEventListener('close',()=>{enrollmentEpoch++;stopEnrollStream();enrollment=null;});$('#help').onclick=()=>{$('#help-dialog').showModal();hydrate($('#help-dialog'));};$('#close-help').onclick=()=>$('#help-dialog').close();window.addEventListener('hashchange',render);window.addEventListener('pagehide',()=>{stopStream();stopEnrollStream();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&!busy){stopCameraUI();stopEnrollStream();}});hydrate();render();
